  VALUES 
    (603::BIGINT, 'Es una gran profesora. Siempre está dispuesta a ayudar a los estudiantes en cualquier sentido. Casi que no deja tareas. Es muy sencillo pasar, pero si no te interesa la clase y no haces un trabajo puede afectar la nota final (al ser pocos trabajos el porcentaje de cada uno es alto).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-09-09T00:00:00+00:00'::TIMESTAMPTZ, '4a9d527499cbe18670a3a48c25b1fe1c5914087a610ecdee06caad3e7186aca7'::TEXT, ARRAY[1620]::BIGINT[]),
    (603::BIGINT, 'Es una excelente profesora. Siempre intenta ayudar a sus estudiantes en todo lo que está a su alcance y es muy estricta con la asistencia. Si tiene la oportunidad de matricular con ella, hágalo. Será una muy bonita experiencia, sobre todo si es de primer ingreso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2b73091e930a3d8d2591c59d3247829a757d1a74306f979c0568c64fd7d15c3f'::TEXT, ARRAY[1620]::BIGINT[]),
    (603::BIGINT, 'Excelente profesora, super buena gente y brinda un apoyo increible, sus clases son dinamicas y todo lo explica super claro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'fbbb5e1406570b376e35c6ff0fd97d83653f6e17619b56131ad851f74538c021'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Es una excelente profesora y ayuda mucho al estudiante, si no entiende repite el ejercicio hasta que lo entienda, super recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-14T00:00:00+00:00'::TIMESTAMPTZ, '79944987d51220b8c852989fc4cb75402da149ea6a5f44f32598272cf4ac32b9'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'La mejor profesora de matemáticas que he tenido en mi vida. Hace presentaciones, explica muy claro, atiende dudas con paciencia, califica suave y se preocupa porque todos pasen, hasta nos dio charlas motivacionales. Excelente profesora y persona, desearía llevar con ella de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-10-18T00:00:00+00:00'::TIMESTAMPTZ, '8a76e114de60ebc759e5ba0bbbf6945c004b7658e9d320984c9c3a89e6a834d4'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Es una profesora excelente, es muy amigable y graciosa, pero también es bastante centrada con las clases y no suele distraerse. Explica muy bien la materia y siempre da ejemplos, hasta que uno entienda. Siempre se preocupa por el aprendizaje de los estudiantes. Califica justo y bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b93878e52183be0320e3610a9962c25f8dca97400f69d4b88057e3857219d63b'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Excelente profesora, se nota que tiene un gran interés por los estudiantes y quiere que todos aprueben el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-10T00:00:00+00:00'::TIMESTAMPTZ, '8be088625e392672249809971eecac40d8b4ed39bff3ffadfe7ff5d70d52f315'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Vaya a consulta si puede con ella, explica muy claro y le va ayudar siempre que pueda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '354d9f79b5ea5d8a82a171c83152a14d13c2d819467fc5b430696d2cccaefa3e'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Es súper ordenada, las clases las da en presentaciones. Da puntos por tener el cuaderno ordenado, es un amor de persona, explica súper bien, tiene evaluaciones grupales un toque weisas pero se logran pasar, y en los exámenes no califica tan duro, es muy justa. Súper recomendada si es primera vez.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '1a9a743f28672075e2bdac435a0bcf231a6221640a057945897b8362e1b2f306'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Como profesora es muy buena y como persona lo es mas, califica justo y da retroalimentación, le pone mucho amor al trabajo y eso se nota en las presentaciones y videos que ella hace'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '037dad4ce2d001ff05b3d31a7be16c727d3c0f1e2243ff6be93407d6d49fb444'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'La profe es un amor, ella explica muy bien y evalua justamente lo que se ver en clases. A diferencia de muchos, ella quiere que todos apruebe el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'd6cdb777d3613c344c032e4fc724383e1a4ae6e3f5bf2819f04c15f43fa6ad7a'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Deja trabajos largos']::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'f55609ac7d95deeccdf68d84c762386a68137e40b04539a49273d92b82808500'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'La profe se esfuerza con las presentaciones y explica bastante bien, al principio era estricta, pero atiende muy bien las dudas y da mucho material de estudio y práctica. Muy linda la profe, recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'fe9a0726f892983c99ee1fb820d2ac7b457d1a9cacc9f00c021031bc2a31adaa'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Explica muy bien y atiende siempre las consultas'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9aed7a8d3ec7fc36b346f8d9ca45a2f5b5cd3078b32f980e8fa258a255bb5278'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Es una excelente profe, y ser humano. Es muy amable, comprensiva y es fácil encariñarse con ella. Además, explica muy bien. Súper recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '1d90fe4517cb061728431e7dd63db1a61e1e7e63d9d13c1423e33c26cfdf70ef'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Es un amor de persona y es una increible profesora, de verdad de las mejores que he tenido, es super atenta con los estudiantes y brinda mucho apoyo. Sus clases son muy buenas y ensaña super bien, definitivamente si puede llevar con ella hágalo!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-04-06T00:00:00+00:00'::TIMESTAMPTZ, 'd46fc37ef51f772455aae9c9977ffeb70c1d7afaf05ef3dce0cbde18dfe53fc6'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'La profe explica de manera excelente y dependiendo de la complejidad del tema, da clases una vez a la semana. Trabaja con portafolio en parejas, pero se puede hacer individual. Recomiendo hacer el portafolio en parejas ya que sirve como practica de lo visto en clase. No pide muchos trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'd7b2a93de14f9dab880835863afbd2ed23a35bdcb68b9b52c7d8dc1ed25b7db0'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Es una super buena profe, usa los videos de la cátedra y los propios de base(asi que es necesario verlos antes de la clase), hace muchos ejercicios, ayuda muchísimo si uno se acerca a ella y es muy considerada. Entregas de tareas puntuales'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'b5b2f04850245735378f7099cfff20d76d12858ac08f26ef5eb87591a7ce31a6'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3ab1ae0fb75ec796b3e0c68fa722858bd650d985e5d1b349be2bb7739611ac22'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Ayuda mucho con sus quices, explica muy bien, es ordenada. Además contesta las dudas por correo muy rápido.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '75f81490bcdbc014003dc71ed46dd395c60e0437c24a82fd36b7ac5a9c0efe5b'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'La profe es super buena, explica muy bien y se interesa porque aprendamos, las tareas son regaladas. Matricule con ella si quiere aprender.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7d019f12866adf328001ef0dcc55f73e71500795f50ee53bd9ab25c5311f57dd'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '3536e872ecf1f82b0ffecd01adcce224d347f3f12d1aeaaed4c33731104b6773'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Excelente profe!! Explica muy bien la materia y siempre está dispuesta a ayudarle y aclarar dudas. Motiva a los estudiantes y realmente se esfuerza por que aprendan. Las clases son muy completas y lo preparan para los quices y exámenes. No dude en matricular con ella!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '56ad83b31f6b88ddaa14d6b367ada789b75e4fef7258ecaf22c3b8c5a662b685'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Es una muy buena profesora, se preocupa por sus estudiantes y su aprendizaje. Es bastante ordenada, lleva las notas al día. Hace muchos ejercicios en clase que ayudan a prepararse para el examen La recomiendo :)!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '052c76f0e98e449cdb2497b91a0b38a77bbeaafc88e5f13e8bfb83563880214e'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'La profesora es muy buena gente y muy paciente. Explica demasiado bine y a veces se entrsitece porque los alumnos no se conectan a la clase. Aclara dudas y no califica ni duro ni suave, lo normal. Se prepara con las clases y es ordenada con los ejemplos que da, que son muchos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '5277afbfd44f6f4b88a2d7348ef4bae3f08e948094a0d07ecbb17dcfcc2508a9'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Es una profesora excelente, se esmera para que el estudiante entienda y explica con demasiada claridad, deja trabajos semanales y tiene mucha facilidad para la tecnología y para atender dudas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '14ed50ac2bfad989c9f3736a64433ed0f28d1b45f51b4d82e963b64a13342e13'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'En clases virtuales fue una excelente profesora, dejó ejercicios y pequeños quices para que uno se mantenga practicando. Responde con rapidez las dudas por correo. La recomiendo 100%.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '37091518dff8ea0d56f7bc6f248a3f8111138e9c7ad309af809ef2a4fb88ec11'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Excelente profesora, las clases son un poco largas pero ella de verdad se esmera porque todos entiendan, hace bastantes ejercicios y le gusta que participen. Siempre está dispuesta ayudar. La recomiendo 100% para cualquier curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-01-13T00:00:00+00:00'::TIMESTAMPTZ, '72115c9fdfd4d7a10a202c2fff1361cafbe30b2cfe121784b2881c469033e153'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Excelente profesora, las clases son muy extensas pero ella de verdad se esmera porque todos entiendan, hace bastantes ejercicios y le gusta que participen. Atiende muy rápido vía telegram y de verdad está dispuesta ayudar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '7c2bd621aeb7ca6dd79de328e6a8e09cfdff56681c5bf9d8144d545083f8ad48'::TEXT, ARRAY[563]::BIGINT[]),
    (603::BIGINT, 'Excelente profesora, no deja al estudiante botado, si puede matricule con ella! Es un amor! Graba toda las clases, resuelve dudas y apoya mucho al estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '384c580b496bf6d158f72337c473bae644e86df12db3b207edd416ca0124dfd1'::TEXT, ARRAY[605]::BIGINT[]),
    (603::BIGINT, 'Graba las clases pero son muy largas y tiene muy pocos espacios de consulta pero puede atender dudas vía Telegram y contesta muy rápido'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '34ac70a4163f8bf26730a9b7af68b269edfcae15ed160333fa0e66a669afc430'::TEXT, ARRAY[563]::BIGINT[]),
